<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
import DocumentAnalysis from './DocumentAnalysis.vue';
import ConsolidationPanel from './ConsolidationPanel.vue';
import PublicationsPanel from './PublicationsPanel.vue';
import AmendmentLinks from './AmendmentLinks.vue';
type Document={numero_registro:string;tipo:string;cliente_original_id:number;clientes_ids:number[];original_disponivel:boolean};
type Link={aditivo:string;base:string|null;justificativa:string;revisao:number};
type Detail={numero_registro:string;numero_solicitacao:string;tipo:string;vigencia:string;partes:string;analise_status:string;analise_concluida_em:string|null;analise:unknown;analise_visao?:{versao?:string;secoes?:Array<{titulo:string;grupos:Array<{titulo:string|null;campos:Array<{id:string;rotulo:string;valor:string;clausula?:string;citacao?:string}>}>}>}|null};
const props=defineProps<{canEdit:boolean;canPublish:boolean;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
const emit=defineEmits<{success:[message:string]}>();
const reviewBase=ref(''), managingLinks=ref(false);
async function linksSaved(message:string){managingLinks.value=false;emit('success',message);await load();}
const bases=computed(()=>documents.value.filter(item=>/conven[çc][ãa]o coletiva/i.test(item.tipo)&&!/aditivo/i.test(item.tipo)));
const documents=ref<Document[]>([]),links=ref<Link[]>([]),clients=ref<Array<{id:number;razao_social:string;nome_fantasia:string}>>([]),loading=ref(true),error=ref(''),query=ref(''),type=ref(''),order=ref('desc'),selected=ref<Document|null>(null),detail=ref<Detail|null>(null),detailError=ref(''),tab=ref('info'),area=ref('instrumentos'),downloading=ref(false);let alive=true,sequence=0;
const filtered=computed(()=>documents.value.filter(item=>item.numero_registro.toLowerCase().includes(query.value.trim().toLowerCase())&&(!type.value||item.tipo===type.value)).sort((a,b)=>a.numero_registro.localeCompare(b.numero_registro,'pt-BR')*(order.value==='desc'?-1:1)));
const relatedLinks=computed(()=>links.value.filter(item=>item.base===selected.value?.numero_registro||item.aditivo===selected.value?.numero_registro));
const relatedClients=computed(()=>clients.value.filter(item=>selected.value?.clientes_ids?.map(String).includes(String(item.id))));
async function load(){const current=++sequence;loading.value=true;error.value='';try{const [catalog,people]=await Promise.all([props.request<{documentos:Document[];vinculos:Link[]}>('/api/contexto/interpretacoes'),props.request<Array<{id:number;razao_social:string;nome_fantasia:string}>>('/api/contexto/clientes')]);if(!alive||current!==sequence)return;documents.value=catalog.documentos;links.value=catalog.vinculos;clients.value=people;}catch(cause){if(alive&&current===sequence)error.value=(cause as Error).message;}finally{if(alive&&current===sequence)loading.value=false;}}
async function open(item:Document){const current=++sequence;selected.value=item;detail.value=null;detailError.value='';tab.value='info';try{const data=await props.request<Detail>('/api/contexto/interpretacoes?numero='+encodeURIComponent(item.numero_registro));if(alive&&current===sequence)detail.value=data;}catch(cause){if(alive&&current===sequence)detailError.value=(cause as Error).message;}}
function close(){sequence++;selected.value=null;detail.value=null;}
async function original(){if(!selected.value||downloading.value)return;const item=selected.value;downloading.value=true;detailError.value='';try{const file=await props.download(`/api/contexto/clientes/${item.cliente_original_id}/documentos/original?numero=${encodeURIComponent(item.numero_registro)}`);if(!alive||selected.value!==item)return;const url=URL.createObjectURL(file.blob),link=document.createElement('a');link.href=url;link.download=item.numero_registro.replace(/[^A-Z0-9_-]/gi,'_')+(file.type.includes('application/pdf')?'.pdf':'.doc');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(cause){if(alive&&selected.value===item)detailError.value=(cause as Error).message;}finally{downloading.value=false;}}
void load();onBeforeUnmount(()=>{alive=false;sequence++;});
</script>
<template><nav class="registry-tabs" aria-label="Áreas de documentos"><button v-for="[key,label] in [['instrumentos','Instrumentos'],['revisoes','Revisões'],...(canPublish?[['publicacoes','Publicações'],['acessos','Acessos e ciência']]:[])]" :key="key" type="button" :aria-pressed="area===key" @click="area=key">{{ label }}</button></nav>
<section v-if="area==='revisoes'"><div class="registry-controls"><label>CCT para revisão<select v-model="reviewBase"><option value="">Selecione uma CCT</option><option v-for="item in bases" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label></div><ConsolidationPanel :base="reviewBase" :can-edit="canEdit" :clients="clients" :request="request" :download="download" @success="emit('success',$event)" /></section>
<PublicationsPanel v-else-if="canPublish&&(area==='publicacoes'||area==='acessos')" :area="area" :clients="clients" :bases="bases" :request="request" :download="download" @success="emit('success',$event)" />
<section v-else-if="area!=='instrumentos'"><p>Você não tem permissão para esta área.</p></section>
<template v-else><div class="document-summary"><article><small>Instrumentos</small><strong>{{ documents.length }}</strong></article><article><small>Convenções coletivas</small><strong>{{ documents.filter(item=>/convenção/i.test(item.tipo)&&!/aditivo/i.test(item.tipo)).length }}</strong></article><article><small>Aditivos</small><strong>{{ documents.filter(item=>/aditivo/i.test(item.tipo)).length }}</strong></article><article><small>Vínculos confirmados</small><strong>{{ links.filter(item=>item.base).length }}</strong></article></div>
<div class="registry-controls"><label>Buscar instrumento<input v-model="query" type="search" placeholder="Número do registro"></label><label>Tipo de instrumento<select v-model="type"><option value="">Todos os tipos</option><option v-for="value in [...new Set(documents.map(item=>item.tipo))]" :key="value">{{ value }}</option></select></label><label>Ordenar<select v-model="order"><option value="desc">Número decrescente</option><option value="asc">Número crescente</option></select></label><button v-if="canEdit" class="secondary" type="button" :disabled="loading||!!error" @click="managingLinks=true">Gerenciar vínculos de aditivos</button><button class="secondary" type="button" :disabled="loading" @click="load">Atualizar lista</button></div><p v-if="loading" role="status">Carregando instrumentos…</p><p v-else-if="error" role="alert">{{ error }}</p><div v-else class="registry-scroll"><table><caption>Instrumentos deste escritório</caption><thead><tr><th scope="col">Documento</th><th scope="col">Tipo</th><th scope="col">Original</th><th scope="col">Ações</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.numero_registro"><td><strong>{{ item.numero_registro }}</strong></td><td>{{ item.tipo }}</td><td>{{ item.original_disponivel?'Disponível':'Pendente' }}</td><td><button class="secondary" type="button" :aria-label="'Abrir ficha de '+item.numero_registro" @click="open(item)">Abrir ficha</button></td></tr><tr v-if="!filtered.length"><td colspan="4">{{ documents.length?'Nenhum resultado para esta busca.':'Ainda não há instrumentos neste escritório.' }}</td></tr></tbody></table></div></template>
<AmendmentLinks v-if="managingLinks&&canEdit" :documents="documents" :links="links" :request="request" @close="managingLinks=false" @saved="linksSaved" />
<AppDialog v-if="selected" title="Ficha do documento" @close="close"><div class="document-identity"><div><small>Instrumento coletivo</small><h2>{{ selected.numero_registro }}</h2><p>{{ selected.tipo }}</p></div><button v-if="selected.original_disponivel" class="secondary" type="button" :disabled="downloading" @click="original">{{ downloading?'Baixando…':'Baixar original' }}</button></div><p v-if="detailError" role="alert">{{ detailError }}</p><p v-if="!detail&&!detailError" role="status">Carregando ficha…</p><template v-if="detail"><nav class="registry-tabs" aria-label="Conteúdo do instrumento"><button v-for="[key,label] in [['info','Visão geral'],['original','Original'],['analysis','Análise'],['consolidacao','Consolidação'],['aditivos','Aditivos'],['clientes','Clientes']]" :key="key" type="button" :aria-pressed="tab===key" @click="tab=key">{{ label }}</button></nav><div v-if="tab==='info'" class="document-info-grid"><article v-for="[label,value] in [['Solicitação',detail.numero_solicitacao],['Tipo de instrumento',detail.tipo],['Vigência',detail.vigencia],['Partes',detail.partes],['Situação da análise',detail.analise_status==='analisado'?'Análise concluída':detail.analise_status],['Análise concluída em',detail.analise_concluida_em?new Date(detail.analise_concluida_em).toLocaleString('pt-BR'):'Não informado']]" :key="label||''"><small>{{ label }}</small><p>{{ value||'Não informado' }}</p></article></div><DocumentAnalysis v-else-if="tab==='analysis'" :view="detail.analise_visao" :analysis="detail.analise" /><section v-else-if="tab==='original'"><h3>Documento original</h3><p>O original é a fonte para conferir a análise e as decisões.</p><button v-if="selected.original_disponivel" type="button" class="secondary" :disabled="downloading" @click="original">Baixar original</button><p v-else>Original ainda não disponível.</p></section><section v-else-if="tab==='aditivos'"><h3>Aditivos vinculados</h3><p v-if="!relatedLinks.length">Nenhum vínculo confirmado.</p><article v-for="link in relatedLinks" :key="link.aditivo" class="document-related"><strong>{{ link.aditivo }}</strong><p>CCT vinculada: {{ link.base||'Não vinculada' }}</p><p>{{ link.justificativa }}</p></article></section><section v-else-if="tab==='clientes'"><h3>Clientes relacionados</h3><p v-if="!relatedClients.length">Nenhum cliente relacionado.</p><article v-for="client in relatedClients" :key="client.id" class="document-related"><strong>{{ client.nome_fantasia||client.razao_social }}</strong><p>{{ client.razao_social }}</p></article></section><ConsolidationPanel v-else :base="selected.numero_registro" :can-edit="canEdit" :clients="clients" :request="request" :download="download" @success="emit('success',$event)" /></template></AppDialog>
</template>
